#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;

int n, m;
int cap[2002][2002];
vector<int> adj[2002];
bool visited[2002];
int parent[2002];

int directions[][2] = { {1,0}, {0,1}, {-1,0}, {0,-1} };

int augment(int u) {
    if (u == 1) return INF;
    visited[u] = true;
    for (auto v : adj[u]) {
        if (!visited[v] && cap[u][v] > 0) {
            int flow = augment(v);
            if (flow > 0) {
                parent[v] = u;
                return min(flow, cap[u][v]);
            }
        }
    }
    return 0;
}

int max_flow() {
    int total = 0;
    while (true) {
        memset(visited, false, sizeof(visited));
        int flow = augment(0);
        if (flow == 0) break;
        total += flow;
        int v = 1;
        while (v != 0) {
            int u = parent[v];
            cap[u][v] -= flow;
            cap[v][u] += flow;
            v = u;
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    int size, time_limit;
    cin >> size >> time_limit;

    for (int i = 0; i < 2 * size * size + 2; ++i) {
        adj[i].clear();
        for (int j = 0; j < 2 * size * size + 2; ++j)
            cap[i][j] = 0;
    }

    vector<string> sci(size), capLab(size);
    int vert[50][50][2];
    int malfunctionIdx;

    n = 2;
    for (int i = 0; i < size; ++i) {
        cin >> sci[i];
        for (int j = 0; j < size; ++j) {
            if (sci[i][j] >= '1' && sci[i][j] <= '9') {
                cap[0][n] = sci[i][j] - '0';
                adj[0].push_back(n);
                adj[n].push_back(0);
                vert[i][j][0] = n++;
            } else if (sci[i][j] == 'Z') {
                malfunctionIdx = 100 * i + j;
                sci[i][j] = 'Y';
            }
        }
    }

    m = n;
    for (int i = 0; i < size; ++i) {
        cin >> capLab[i];
        for (int j = 0; j < size; ++j) {
            if (capLab[i][j] >= '1' && capLab[i][j] <= '9') {
                cap[m][1] = capLab[i][j] - '0';
                adj[m].push_back(1);
                vert[i][j][1] = m++;
            }
        }
    }

    int die[50][50];
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j)
            die[i][j] = time_limit + 1;
    die[malfunctionIdx / 100][malfunctionIdx % 100] = 0;

    queue<int> q;
    q.push(malfunctionIdx);
    while (!q.empty()) {
        int x = q.front(); q.pop();
        int y = x % 100; x /= 100;
        for (auto d : directions) {
            int nx = x + d[0], ny = y + d[1];
            if (nx >= 0 && nx < size && ny >= 0 && ny < size && sci[nx][ny] != 'Y' && die[nx][ny] > die[x][y] + 1) {
                die[nx][ny] = die[x][y] + 1;
                q.push(100 * nx + ny);
            }
        }
    }

    int reach[50][50];
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j)
            reach[i][j] = time_limit + 1;

    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            if (sci[i][j] >= '1' && sci[i][j] <= '9') {
                for (int x = 0; x < size; ++x)
                    for (int y = 0; y < size; ++y)
                        reach[x][y] = time_limit + 1;
                reach[i][j] = 0;
                if (capLab[i][j] >= '1' && capLab[i][j] <= '9') {
                    cap[vert[i][j][0]][vert[i][j][1]] = INF;
                    adj[vert[i][j][0]].push_back(vert[i][j][1]);
                    adj[vert[i][j][1]].push_back(vert[i][j][0]);
                }
                queue<int> q2;
                q2.push(100 * i + j);
                while (!q2.empty()) {
                    int x = q2.front(); q2.pop();
                    int y = x % 100; x /= 100;
                    for (auto d : directions) {
                        int nx = x + d[0], ny = y + d[1];
                        if (nx >= 0 && nx < size && ny >= 0 && ny < size && sci[nx][ny] != 'Y' && reach[nx][ny] > reach[x][y] + 1) {
                            if (capLab[nx][ny] >= '1' && capLab[nx][ny] <= '9') {
                                if (reach[x][y] + 1 <= die[nx][ny]) {
                                    cap[vert[i][j][0]][vert[nx][ny][1]] = INF;
                                    adj[vert[i][j][0]].push_back(vert[nx][ny][1]);
                                    adj[vert[nx][ny][1]].push_back(vert[i][j][0]);
                                }
                            }
                            if (reach[x][y] + 1 < die[nx][ny]) {
                                reach[nx][ny] = reach[x][y] + 1;
                                q2.push(100 * nx + ny);
                            }
                        }
                    }
                }
            }
        }
    }

    cout << max_flow() << endl;
    return 0;
}
